'use strict';
const learningUnit=id=>LEARNING_UNITS.find(u=>u.id===Number(id))||LEARNING_UNITS[0];
function linkedListeningMaterial(c){const u=learningUnit(c.id),a=shadowTrack(c.id);return `<section class="linked-material" aria-label="本周听力与写作材料"><span class="eyebrow">ONE MATERIAL / LISTEN → WRITE</span><h3>W${c.id} 听力与邮件共用材料</h3><p>${esc(a.title)}</p><audio controls preload="none" src="${esc(AUDIO_TIMINGS[c.id].url)}"></audio><div class="btn-row"><a class="article-link" href="#audio/${c.id}">逐句跟读本周材料 ↗</a></div><details><summary>查看同一份听力原文</summary><div class="english-text">${esc(a.segments.map(s=>s[0]).join('\n\n'))}</div></details><h4>写作时核对这些事实</h4><ul class="step-list">${u.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="source-note">练习邮件使用这段录音，不借用其他周的人物、数字或期限。未给出的信息可提出询问。</p></section>`;}
function practiceReference(c,kind){const u=learningUnit(c.id),writing=kind==='writing';return `<details class="practice-reference" open><summary>${writing?'同材料邮件标准范文':'根据你简历整理的标准回答'}</summary><div class="english-text">${esc(writing?u.email:c.sample)}</div>${writing?'<p class="sub">对照目的、事实、请求与下一步修改首稿。录音中的工作情境属于模拟练习。</p>':`<p class="sub">${esc(c.translation)}</p><p class="source-note">经历依据：${esc(c.answerSource)}</p>`}<div class="btn-row"><button type="button" class="btn secondary small" data-learning-copy="${c.id}" data-kind="${kind}">复制${writing?'邮件范文':'标准回答'}</button>${writing?'':`<button type="button" class="btn light small" data-action="speak-sample" data-id="${c.id}">▷ 朗读回答</button>`}</div></details>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-learning-copy]');if(b){const u=learningUnit(b.dataset.learningCopy);copy(b.dataset.kind==='writing'?u.email:u.answer);}});
